<?php namespace App\Models;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;class User extends Authenticatable{use Notifiable;protected $fillable=['name','email','password','role','phone','address'];protected $hidden=['password','remember_token'];protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];}public function children(){return $this->hasMany(Child::class,'parent_id');}public function hospital(){return $this->hasOne(Hospital::class);}}
